def construir_arbol(rutas):
    arbol = {}
    for ruta in rutas:
        segmentos = ruta.split('/')
        nodo_actual = arbol
        for i, segmento in enumerate(segmentos):
            if i == len(segmentos) - 1:
                # Es el último segmento de la ruta actual, debe ser un diccionario vacío
                nodo_actual[segmento] = {}
            else:
                # No es el último, debe ser un diccionario que contenga el siguiente nivel
                if segmento not in nodo_actual:
                    nodo_actual[segmento] = {}
                nodo_actual = nodo_actual[segmento]
    return arbol
