def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar los intervalos por el valor de inicio
    sorted_intervals = sorted(intervalos, key=lambda x: x[0])

    merged = []
    for current in sorted_intervals:
        # Si la lista está vacía o el intervalo actual no se solapa/toca con el último añadido
        if not merged or current[0] > merged[-1][1]:
            merged.append(current)
        else:
            # Fusionar con el último intervalo de la lista de resultados
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged
