def descifrar(datos, clave):
    if not clave:
        raise ValueError("La clave no puede estar vacía.")

    resultado = bytearray()
    for i in range(len(datos)):
        resultado.append(datos[i] ^ clave[i % len(clave)])

    return bytes(resultado)
