import heapq

def orden_topologico(dependencias: dict[str, list[str]]) -> list[str]:
    # Identificar todos los nodos únicos (claves y dependencias)
    all_nodes = set(dependencias.keys())
    for deps in dependencias.values():
        for d in deps:
            all_nodes.add(d)

    # Construir el grafo de adyacencia (quién depende de quién)
    # y contar el grado de entrada (cuántas dependencias tiene cada tarea)
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for task, deps in dependencias.items():
        # El input dice que 'deps' son tareas que deben ir ANTES de 'task'
        # Por lo tanto, la relación es: dep -> task
        in_degree[task] = len(set(deps))
        for d in set(deps):
            adj[d].append(task)

    # Usar un min-heap para garantizar el orden alfabético entre tareas disponibles
    # Las tareas disponibles son aquellas con in_degree == 0
    ready_tasks = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready_tasks)

    result = []
    while ready_tasks:
        current = heapq.heappop(ready_tasks)
        result.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(ready_tasks, neighbor)

    # Si el resultado no contiene todos los nodos, hay un ciclo
    if len(result) != len(all_nodes):
        raise ValueError("Ciclo detectado en las dependencias")

    return result
